local skada = {120, 300, 95}
table.sort(skada, function(a, b) return a > b end)
print(table.concat(skada, ", "))

local raid = {"Präst", "Krigare", "Präst"}
local antal = {}
for _, k in ipairs(raid) do
  antal[k] = (antal[k] or 0) + 1
end
local namn = {}
for k in pairs(antal) do table.insert(namn, k) end
table.sort(namn)
for _, k in ipairs(namn) do print(k .. " " .. antal[k]) end
